**text.css — Heading and text sizes per layout**

[text.css#L44-L99](file:///Users/dwahl/Scripts/pantoken/renderers/pendo/src/css/text.css#L44-L99):
```css
/* Alert titles match relaxed banners; subtitles match compact banner titles. */
:is(:scope[class*="instui-alert"], [class*="instui-alert"])[data-layout="lightboxBlank"] {
  h2._pendo-simple-text {
    font-size: var(--instui-component-heading-title-card-regular-font-size);
    font-weight: var(--instui-component-heading-title-card-regular-font-weight);
    line-height: var(--instui-component-heading-title-card-regular-line-height);
  }

  h3._pendo-simple-text {
    font-size: var(--instui-component-heading-title-card-mini-font-size);
    font-weight: var(--instui-component-heading-title-card-mini-font-weight);
    line-height: var(--instui-component-heading-title-card-mini-line-height);
  }
}

/* Popover titles match compact banners; subtitles are one font token smaller. */
[data-layout="tooltipBlank"] {
  h2._pendo-simple-text {
    font-size: var(--instui-component-heading-title-card-mini-font-size);
    font-weight: var(--instui-component-heading-title-card-mini-font-weight);
    line-height: var(--instui-component-heading-title-card-mini-line-height);
  }

  h3._pendo-simple-text {
    font-size: var(--instui-font-size-text-sm);
    font-weight: var(--instui-component-heading-title-card-mini-font-weight);
    line-height: var(--instui-component-heading-title-card-mini-line-height);
  }
}

/* [...lists and links...] */

/* Surveys*/
._pendo-guide-walkthrough_:not([data-layout="tooltipBlank"], [data-layout="lightboxBlank"]) {
  /* @TODO: Surveys are terrible, clean this up. */

  & *:not(._pendo-close-guide) {
    font-size: var(--instui-component-heading-title-card-mini-font-size);
  }
  /* [...survey-specific text styling...] */
}

/* Banner typography follows the banner container rather than an authored size class. */
:is(:scope, [class*="instui"])[data-layout="lightboxBlank"]:not([class*="instui-alert"]) {
  :is(._pendo-simple-text, [class*="_pendo-text-"]) {
    font-size: var(--instui-component-text-content-font-size);
    font-weight: var(--instui-component-text-content-font-weight);
    line-height: var(--instui-component-text-content-line-height);
  }

  :is(h2._pendo-simple-text, h2._pendo-text-title) {
    font-size: var(--instui-component-heading-title-card-regular-font-size);
    font-weight: var(--instui-component-heading-title-card-regular-font-weight);
    line-height: var(--instui-component-heading-title-card-regular-line-height);
  }

  h3._pendo-simple-text {
    font-size: var(--instui-component-heading-title-card-mini-font-size);
    font-weight: var(--instui-component-heading-title-card-mini-font-weight);
    line-height: var(--instui-component-heading-title-card-mini-line-height);
  }
}

@container pantoken-pendo-guide (max-width: 30em) {
  :is(:scope, [class*="instui"])[data-layout="lightboxBlank"]:not([class*="instui-alert"]) {
    :is(._pendo-simple-text, [class*="_pendo-text-"]) {
      font-size: var(--instui-component-text-content-small-font-size);
      font-weight: var(--instui-component-text-content-small-font-weight);
      line-height: var(--instui-component-text-content-small-line-height);
    }

    :is(h2._pendo-simple-text, h2._pendo-text-title) {
      font-size: var(--instui-component-heading-title-card-mini-font-size);
```

